//! Spike #6 probe: how Pasta can watch NSPasteboard, mark its own writes and
//! spot iCloud Universal Clipboard items.
//!
//! Run on a Mac with `cargo run -p pasta-clipboard --example mac_pasteboard_probe -- [watch|write] [seconds]`.
//!
//! * `watch` (default): polls `changeCount` and prints the types of every new
//!   item, the frontmost app, and whether it is concealed / transient /
//!   auto-generated / from Universal Clipboard. Copy things on the Mac, then
//!   copy on an iPhone or iPad signed into the same Apple ID.
//! * `write`: writes a marker item with a custom Pasta type, then watches so
//!   you can check whether it reaches the iPhone/iPad and whether the marker
//!   type survives a round trip.
//!
//! Prints type names and lengths only, never clipboard text.

#![allow(clippy::print_stdout)]

#[cfg(not(target_os = "macos"))]
fn main() {
    println!("mac_pasteboard_probe only runs on macOS");
}

#[cfg(target_os = "macos")]
fn main() {
    probe::run();
}

#[cfg(target_os = "macos")]
mod probe {
    use std::time::{Duration, Instant};

    use objc2_app_kit::{NSPasteboard, NSPasteboardTypeString, NSWorkspace};
    use objc2_foundation::{NSDate, NSRunLoop, NSString};

    const POLL_INTERVAL: Duration = Duration::from_millis(250);
    const MARKER_TYPE: &str = "dev.pasta.origin";
    /// Conventions from nspasteboard.org honoured by password managers.
    const CONCEALED: &str = "org.nspasteboard.ConcealedType";
    const TRANSIENT: &str = "org.nspasteboard.TransientType";
    const AUTO_GENERATED: &str = "org.nspasteboard.AutoGeneratedType";
    /// Set on items that arrived through Universal Clipboard.
    const REMOTE_CLIPBOARD: &str = "com.apple.is-remote-clipboard";
    /// Page or extension a Chromium-based app copied from.
    const CHROMIUM_SOURCE_URL: &str = "org.chromium.source-url";

    pub fn run() {
        let mut args = std::env::args().skip(1);
        let mode = args.next().unwrap_or_else(|| "watch".to_owned());
        let seconds: u64 = args.next().and_then(|s| s.parse().ok()).unwrap_or(60);

        let pasteboard = NSPasteboard::generalPasteboard();
        if mode == "write" {
            write_marker(&pasteboard);
        }
        watch(&pasteboard, Duration::from_secs(seconds));
    }

    fn write_marker(pasteboard: &NSPasteboard) {
        let text = NSString::from_str("pasta-spike-marker");
        let marker_type = NSString::from_str(MARKER_TYPE);
        pasteboard.clearContents();
        let wrote_text = pasteboard.setString_forType(&text, unsafe { NSPasteboardTypeString });
        let wrote_marker = pasteboard.setString_forType(&NSString::from_str("1"), &marker_type);
        println!("wrote marker item: text={wrote_text} marker={wrote_marker} changeCount={}", pasteboard.changeCount());
    }

    fn watch(pasteboard: &NSPasteboard, duration: Duration) {
        println!("watching for {}s, polling every {} ms", duration.as_secs(), POLL_INTERVAL.as_millis());
        let started = Instant::now();
        let mut last = pasteboard.changeCount();
        let mut polls: u64 = 0;
        while started.elapsed() < duration {
            // Spin the run loop instead of sleeping so NSWorkspace sees app switches.
            NSRunLoop::currentRunLoop()
                .runUntilDate(&NSDate::dateWithTimeIntervalSinceNow(POLL_INTERVAL.as_secs_f64()));
            polls += 1;
            let count = pasteboard.changeCount();
            if count != last {
                last = count;
                report(pasteboard, count, started.elapsed());
            }
        }
        println!("done after {polls} polls");
    }

    fn report(pasteboard: &NSPasteboard, count: isize, at: Duration) {
        let types: Vec<String> =
            pasteboard.types().map(|types| types.iter().map(|t| t.to_string()).collect()).unwrap_or_default();
        let has = |name: &str| types.iter().any(|t| t == name);
        let text_len =
            pasteboard.stringForType(unsafe { NSPasteboardTypeString }).map(|s| s.to_string().chars().count());
        let frontmost = NSWorkspace::sharedWorkspace().frontmostApplication().map(|app| {
            let name = app.localizedName().map(|n| n.to_string()).unwrap_or_default();
            let bundle = app.bundleIdentifier().map(|b| b.to_string()).unwrap_or_default();
            format!("{name} ({bundle})")
        });

        println!("\n[{:>6.1}s] changeCount={count}", at.as_secs_f64());
        println!("  frontmost app: {}", frontmost.unwrap_or_else(|| "none".to_owned()));
        println!("  text chars: {text_len:?}");
        println!(
            "  concealed={} transient={} auto_generated={} universal_clipboard={} pasta_marker={}",
            has(CONCEALED),
            has(TRANSIENT),
            has(AUTO_GENERATED),
            has(REMOTE_CLIPBOARD),
            has(MARKER_TYPE)
        );
        let source_origin =
            pasteboard.stringForType(&NSString::from_str(CHROMIUM_SOURCE_URL)).map(|url| origin(&url.to_string()));
        println!("  chromium source origin: {}", source_origin.unwrap_or_else(|| "none".to_owned()));
        println!("  types: {}", types.join(", "));
    }

    /// `scheme://host` only, so paths and query strings are never printed.
    fn origin(url: &str) -> String {
        match url.split_once("://") {
            Some((scheme, rest)) => format!("{scheme}://{}", rest.split(['/', '?', '#']).next().unwrap_or_default()),
            None => "unparseable".to_owned(),
        }
    }
}
